      ],
      commands: [
        { id: "setDue", label: "设截止", from: ["open"] },
        { id: "expire", label: "标为过期", from: ["open"], internalOnly: true },
      ],
      schedules: [{
        id: "due-expire", atKind: "field", at: "dueAt", dedupeKey: "due-expire",
